    if(travelBtn){travelBtn.innerHTML=blocked?"Открыть проход ⛓":selectedLocation===currentLocation?"Ты на месте":"Выбрать путь →";travelBtn.disabled=travelAnimating||state.inCombat||selectedLocation===currentLocation;}
