    const dyn=$("map-dynamic-nodes"),routes=$("map-dynamic-routes");if(dyn)dyn.innerHTML=Object.entries(MAP_LOCATIONS).filter(([id])=>!["forest","ruins","altar","tavern"].includes(id)).map(([id,n])=>{const revealed=(state.discoveredLocations||[]).includes(id),locked=!mapNodeUnlocked(id);return `<g class="map-location map-dynamic-node ${revealed?"":"is-hidden-by-fog"} ${locked?"is-locked-node":""} ${id===currentLocation?"is-current":""} ${id===selectedLocation?"is-selected":""}" data-location="${id}" role="button" tabindex="${revealed?0:-1}" aria-label="${n.name}${locked?", запечатано":""}" aria-hidden="${!revealed}" aria-pressed="${id===selectedLocation}" transform="translate(${n.x} ${n.y})" style="pointer-events:${revealed?"auto":"none"}"><circle class="node-hit-area" r="25" fill="transparent" pointer-events="all"/><circle class="node-halo" r="22"/><circle class="node-ring" r="16"/><text class="node-glyph" text-anchor="middle" y="6">${locked?"🔒":MAP_NODE_ICONS[id]||"✦"}</text><text y="35" text-anchor="middle">${n.name}</text></g>`;}).join("");
